<script setup>
import { Activity, Archive, ArrowLeft, ArrowRight, BarChart3, Check, ClipboardList, Eye, FileText, FolderTree, Hash, History, Image as ImageIcon, LayoutDashboard, LogOut, Menu, Plus, RefreshCw, Save, Search, Settings, ShieldCheck, Trash2, Upload, Users, X } from 'lucide-vue-next';
import { computed, nextTick, onMounted, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router';
import { categories, posts } from '../data'; import { adminRequest, apiRequest, createAdminToken } from '../api';

const route=useRoute();const router=useRouter();const authed=ref(localStorage.getItem('signal-admin-auth')==='true');const login=ref({email:'admin',password:'signal2026'});const loginError=ref('');const menuOpen=ref(false);const apiStatus=ref('本地数据');
const adminPosts=ref(JSON.parse(localStorage.getItem('signal-admin-posts')||'null')||posts.map(p=>({...p,status:'PUBLISHED'})));const query=ref('');const filter=ref('ALL');const users=ref([{id:1,name:'林默',email:'admin@signal.local',role:'管理员',status:'正常'},{id:2,name:'编辑同事',email:'editor@signal.local',role:'编辑',status:'正常'},{id:3,name:'测试读者',email:'reader@example.com',role:'访客',status:'待确认'}]);
const selectedPosts=ref([]);
const comments=ref([{id:1,authorName:'访客',content:'希望继续写更多真实项目里的 AI 经验。',postSlug:'building-reliable-ai-systems',status:'PENDING'},{id:2,authorName:'测试读者',content:'Local-first 的部分很有启发。',postSlug:'local-first-software',status:'PENDING'}]);const media=ref([]);const settings=ref(JSON.parse(localStorage.getItem('signal-settings')||'{"siteName":"脉冲笔记","tagline":"把复杂技术讲清楚","shareTemplate":"横版卡片","comments":true}'));const saved=ref('');const backup=ref('今天 04:00');
const nav=[['/admin','仪表盘',LayoutDashboard],['/admin/posts','文章',FileText],['/admin/taxonomy','分类与标签',FolderTree],['/admin/media','媒体库',ImageIcon],['/admin/comments','评论',ClipboardList],['/admin/users','用户',Users],['/admin/settings','设置',Settings],['/admin/logs','日志与备份',Activity]];
const section=computed(()=>route.path.split('/')[2]||'dashboard');const editorMode=computed(()=>route.path.includes('/posts/new')||route.path.includes('/edit'));const filteredPosts=computed(()=>adminPosts.value.filter(p=>(!query.value||p.title.includes(query.value))&&(filter.value==='ALL'||p.status===filter.value)));
const editId=computed(()=>route.params.pathMatch?.[1]);const editor=ref({});const editorReady=ref(false);const previewing=ref(false);const revisions=ref([]);const categoriesAdmin=ref([]);const tagsAdmin=ref([]);const taxonomyDraft=ref({name:'',slug:'',description:''});const tagDraft=ref('');
const publishChecklist=computed(()=>[{label:'标题',ok:Boolean(editor.value.title?.trim())},{label:'Slug',ok:Boolean(editor.value.slug?.trim())},{label:'正文',ok:editor.value.content?.trim().length>40},{label:'分类',ok:Boolean(editor.value.category)},{label:'封面替代文本',ok:Boolean(editor.value.coverAlt?.trim())},{label:'SEO 标题与描述',ok:Boolean(editor.value.seoTitle?.trim()&&editor.value.seoDescription?.trim())}]);
function syncEditor(){if(!editorMode.value)return;editorReady.value=false;const id=editId.value;const existing=id?adminPosts.value.find(p=>String(p.id)===String(id)):null;editor.value=existing?{...existing}:{id:`post-${Date.now()}`,title:'',slug:'',excerpt:'',content:'',category:'人工智能',tags:[],status:'DRAFT',cover:'/assets/hero-circuit.jpg',coverAlt:'',readMinutes:5,seoTitle:'',seoDescription:'',canonicalUrl:'',pinned:false,scheduledAt:null};nextTick(()=>{editorReady.value=true;});}
watch(()=>route.path,()=>{menuOpen.value=false;syncEditor();if(editorMode.value)loadRevisions();},{immediate:true});
onMounted(async()=>{if(authed.value) await loadAdminData();});
async function loadAdminData(){try{const [dashboard,postData,commentData,userData,settingData,mediaData,taxonomy,tagsData]=await Promise.all([adminRequest('/admin/dashboard'),adminRequest('/admin/posts'),adminRequest('/admin/comments'),adminRequest('/admin/users'),adminRequest('/admin/settings'),apiRequest('/media'),adminRequest('/admin/categories'),adminRequest('/admin/tags')]);adminPosts.value=postData;comments.value=commentData;users.value=userData;settings.value={...settings.value,...settingData};media.value=mediaData||[];categoriesAdmin.value=taxonomy||[];tagsAdmin.value=tagsData||[];apiStatus.value=`MySQL 已连接 · ${dashboard.posts} 篇文章`;syncEditor();}catch{apiStatus.value='后端未连接 · 本地模式';}}
async function doLogin(){loginError.value='';const token=createAdminToken(login.value.email,login.value.password);try{localStorage.setItem('signal-admin-token',token);await apiRequest('/admin/dashboard',{headers:{Authorization:`Basic ${token}`}});authed.value=true;localStorage.setItem('signal-admin-auth','true');await loadAdminData();}catch{localStorage.removeItem('signal-admin-token');if((login.value.email==='admin'||login.value.email==='admin@signal.local')&&login.value.password==='signal2026'){authed.value=true;localStorage.setItem('signal-admin-auth','true');apiStatus.value='后端未连接 · 本地模式';}else loginError.value='账号或密码不正确';}}
function logout(){authed.value=false;localStorage.removeItem('signal-admin-auth');localStorage.removeItem('signal-admin-token');router.push('/admin');}
function persist(){localStorage.setItem('signal-admin-posts',JSON.stringify(adminPosts.value));}
async function savePost(status=editor.value.status,silent=false){const value={...editor.value,status,updatedAt:new Date().toISOString().slice(0,10),publishedAt:editor.value.publishedAt||new Date().toISOString().slice(0,10),tags:Array.isArray(editor.value.tags)?editor.value.tags:String(editor.value.tags||'').split(',').map(t=>t.trim()).filter(Boolean)};try{const payload={slug:value.slug||value.title.toLowerCase().replace(/\s+/g,'-'),title:value.title,excerpt:value.excerpt||'',content:value.content||'',cover:value.cover,coverAlt:value.coverAlt,category:value.category,tags:value.tags,status:value.status,authorName:'林默',publishedAt:value.publishedAt,readMinutes:Number(value.readMinutes)||5,scheduledAt:value.scheduledAt||null,seoTitle:value.seoTitle||value.title,seoDescription:value.seoDescription||value.excerpt,canonicalUrl:value.canonicalUrl||null,pinned:Boolean(value.pinned)};const result=value.id&&Number.isFinite(Number(value.id))?await adminRequest(`/admin/posts/${value.id}`,{method:'PUT',body:JSON.stringify(payload)}):await adminRequest('/admin/posts',{method:'POST',body:JSON.stringify(payload)});Object.assign(value,result);apiStatus.value='MySQL 已连接';}catch{apiStatus.value='后端未连接 · 已保存到本地';}const i=adminPosts.value.findIndex(p=>String(p.id)===String(value.id));if(i>=0)adminPosts.value[i]=value;else adminPosts.value.unshift(value);persist();saved.value=silent?'自动保存完成':status==='PUBLISHED'?'文章已发布':'草稿已保存';if(!silent)setTimeout(()=>{saved.value='';if(status==='PUBLISHED')router.push('/admin/posts');},500);}
let autosaveTimer;watch(editor,{deep:true},()=>{if(!editorReady.value||!editorMode.value)return;clearTimeout(autosaveTimer);saved.value='有未保存修改';autosaveTimer=setTimeout(()=>savePost('DRAFT',true),1000);});
async function loadRevisions(){if(!editId.value||!Number.isFinite(Number(editId.value)))return;try{revisions.value=await adminRequest(`/admin/posts/${editId.value}/revisions`);}catch{revisions.value=[];}}
async function restoreRevision(id){if(!confirm('恢复此版本会创建新的草稿版本，继续吗？'))return;try{const result=await adminRequest(`/admin/posts/${editId.value}/revisions/${id}/restore`,{method:'POST'});editor.value={...editor.value,...result};saved.value='已恢复为新草稿';await loadRevisions();}catch{saved.value='恢复失败，请重试';}}
async function createCategory(){if(!taxonomyDraft.value.name.trim()||!taxonomyDraft.value.slug.trim())return;try{const result=await adminRequest('/admin/categories',{method:'POST',body:JSON.stringify(taxonomyDraft.value)});categoriesAdmin.value.push(result);taxonomyDraft.value={name:'',slug:'',description:''};}catch{saved.value='分类名称或别名已存在';}}
async function createTag(){if(!tagDraft.value.trim())return;try{const result=await adminRequest('/admin/tags',{method:'POST',body:JSON.stringify({name:tagDraft.value,slug:tagDraft.value.toLowerCase().replace(/\s+/g,'-')})});tagsAdmin.value.push(result);tagDraft.value='';}catch{saved.value='标签已存在';}}
async function toggleUser(user){const previous=user.status;user.status=user.status==='ACTIVE'||user.status==='正常'?'DISABLED':'ACTIVE';try{await adminRequest(`/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({status:user.status})});saved.value='用户状态已更新，会话已失效';}catch{user.status=previous;saved.value='用户状态更新失败';}}
async function bulkStatus(status){if(!selectedPosts.value.length)return;try{await adminRequest('/admin/posts/batch',{method:'PATCH',body:JSON.stringify({ids:selectedPosts.value.map(Number),status})});adminPosts.value.forEach(post=>{if(selectedPosts.value.map(String).includes(String(post.id))){post.status=status;post.deletedAt=status==='TRASHED'?new Date().toISOString():null;}});saved.value=`已更新 ${selectedPosts.value.length} 篇文章`;selectedPosts.value=[];persist();}catch{saved.value='批量操作失败，请重试';}}
async function saveSettings(){try{await adminRequest('/admin/settings',{method:'PUT',body:JSON.stringify(settings.value)});apiStatus.value='MySQL 已连接';}catch{localStorage.setItem('signal-settings',JSON.stringify(settings.value));}saved.value='设置已保存';setTimeout(()=>saved.value='',1800);}
async function moderate(item,status){item.status=status;try{await adminRequest(`/admin/comments/${item.id}`,{method:'PATCH',body:JSON.stringify({status})});}catch{}}
async function deleteComment(item){comments.value=comments.value.filter(c=>c.id!==item.id);try{await adminRequest(`/admin/comments/${item.id}`,{method:'DELETE'});}catch{}}
async function uploadMedia(event){for(const file of event.target.files||[]){try{const body=new FormData();body.append('file',file);const result=await adminRequest('/admin/media',{method:'POST',headers:{},body});media.value.unshift(result);}catch{}}event.target.value='';}
</script>

<template>
  <main v-if="!authed" class="admin-login"><div class="admin-login-mark"><span /><span /><span /></div><span class="admin-kicker">SIGNAL NOTES / ADMIN</span><h1>管理你的<br />技术记录。</h1><p>发布文章、整理媒体和处理读者反馈。</p><form @submit.prevent="doLogin"><label>管理员账号<input v-model="login.email" autocomplete="username" /></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password" /></label><button class="button button-primary">进入后台 <ArrowRight :size="17" /></button><small v-if="loginError">{{loginError}}</small></form><span class="admin-demo-hint">演示账号：admin / signal2026</span></main>
  <div v-else class="admin-shell"><aside :class="{'is-open':menuOpen}"><div class="admin-aside-brand"><span class="brand-mark"><i /><i /><i /></span><div><b>脉冲笔记</b><small>ADMIN / CONSOLE</small></div></div><nav><RouterLink v-for="item in nav" :key="item[0]" :to="item[0]"><component :is="item[2]" :size="17" />{{item[1]}}<em v-if="item[1]==='评论'">{{comments.filter(c=>c.status==='PENDING').length}}</em></RouterLink></nav><div class="admin-aside-bottom"><RouterLink to="/blog"><ArrowRight :size="15" />查看站点</RouterLink><button @click="logout"><LogOut :size="15" />退出登录</button></div></aside><div class="admin-body"><header class="admin-topbar"><button class="admin-menu-toggle" @click="menuOpen=!menuOpen"><X v-if="menuOpen" :size="19" /><Menu v-else :size="19" /></button><div class="admin-breadcrumb">ADMIN <span>/</span> SIGNAL NOTES</div><div class="admin-top-actions"><span class="admin-online"><i />{{apiStatus}}</span><span class="admin-user">林默 · 管理员</span></div></header>
    <main v-if="editorMode" class="admin-content editor-page"><div class="editor-top"><RouterLink to="/admin/posts"><ArrowLeft :size="16" />文章列表</RouterLink><div><span>{{saved||'等待输入'}}</span><button class="button" @click="previewing=!previewing"><Eye :size="15" />{{previewing?'返回编辑':'预览'}}</button><button class="button" @click="savePost('DRAFT')"><Save :size="15" />保存草稿</button><button class="button button-primary" :disabled="publishChecklist.some(item=>!item.ok)" @click="savePost('PUBLISHED')">发布 <ArrowRight :size="15" /></button></div></div><div v-if="previewing" class="editor-live-preview"><span>仅管理员可见 · 当前草稿预览</span><h1>{{editor.title||'未命名文章'}}</h1><p>{{editor.excerpt}}</p><pre>{{editor.content}}</pre></div><div v-else class="editor-grid"><section class="editor-main"><input v-model="editor.title" class="editor-title" placeholder="文章标题" /><textarea v-model="editor.excerpt" class="editor-excerpt" rows="3" placeholder="写一段摘要" /><textarea v-model="editor.content" class="editor-content" placeholder="使用 Markdown 写作..." /><footer class="editor-statusbar"><span>{{(editor.content||'').length}} 字</span><span>约 {{Math.max(1,Math.ceil((editor.content||'').length/500))}} 分钟</span><button type="button" @click="loadRevisions"><History :size="14" />版本历史</button></footer></section><aside class="editor-sidebar"><div class="editor-card"><h3>发布设置</h3><label>状态<select v-model="editor.status"><option value="DRAFT">草稿</option><option value="PENDING">待审核</option><option value="SCHEDULED">定时发布</option><option value="PUBLISHED">已发布</option><option value="OFFLINE">已下线</option><option value="TRASHED">回收站</option></select></label><label v-if="editor.status==='SCHEDULED'">计划时间<input v-model="editor.scheduledAt" type="datetime-local" /></label><label>分类<select v-model="editor.category"><option v-for="cat in (categoriesAdmin.length?categoriesAdmin:categories)" :key="cat.name">{{cat.name}}</option></select></label><label>标签<input v-model="editor.tags" placeholder="AI, 工程" /></label><label>预计阅读分钟<input v-model.number="editor.readMinutes" type="number" min="1" /></label><label class="admin-check"><input v-model="editor.pinned" type="checkbox" />置顶文章</label></div><div class="editor-card"><h3>SEO 与媒体</h3><label>Slug<input v-model="editor.slug" /></label><label>SEO 标题<input v-model="editor.seoTitle" maxlength="240" /></label><label>SEO 描述<textarea v-model="editor.seoDescription" rows="3" maxlength="320" /></label><label>Canonical URL<input v-model="editor.canonicalUrl" type="url" /></label><label>封面 URL<input v-model="editor.cover" /></label><label>图片替代文本<input v-model="editor.coverAlt" /></label></div><div class="editor-card publish-checklist"><h3>发布检查</h3><div v-for="item in publishChecklist" :key="item.label" :class="{ok:item.ok}"><Check :size="14" />{{item.label}}</div></div><div v-if="revisions.length" class="editor-card revision-list"><h3>版本历史</h3><button v-for="item in revisions" :key="item.id" type="button" @click="restoreRevision(item.id)"><span>#{{item.versionNo}} · {{item.editor}}</span><small>{{item.changeSummary}}</small></button></div></aside></div></main>
    <main v-else class="admin-content">
      <template v-if="section==='dashboard'"><header class="admin-page-header"><div><span>OVERVIEW / 001</span><h1>早上好，林默。</h1><p>这里是你的内容工作台，今天也保持一点信号。</p></div><RouterLink class="button button-primary" to="/admin/posts/new"><Plus :size="17" />新建文章</RouterLink></header><section class="admin-stat-grid"><div class="admin-stat"><FileText :size="18" /><span>已发布文章</span><strong>{{adminPosts.filter(p=>p.status==='PUBLISHED').length}}</strong><small>内容持续更新</small></div><div class="admin-stat"><ClipboardList :size="18" /><span>待处理评论</span><strong>{{comments.filter(c=>c.status==='PENDING').length}}</strong><small>需要审核</small></div><div class="admin-stat"><Archive :size="18" /><span>草稿</span><strong>{{adminPosts.filter(p=>p.status==='DRAFT').length}}</strong><small>继续编辑</small></div><div class="admin-stat"><BarChart3 :size="18" /><span>近 7 日访问</span><strong>2,418</strong><small>+18.4%</small></div></section><section class="admin-panel chart-panel"><div class="panel-heading"><div><span>RECENT NOTES</span><h2>最近文章</h2></div><RouterLink to="/admin/posts">查看全部</RouterLink></div><div class="admin-table compact"><RouterLink v-for="post in adminPosts.slice(0,6)" :key="post.id" class="table-row" :to="`/admin/posts/${post.id}/edit`"><strong>{{post.title}}</strong><span>{{post.category}}</span><span class="status">{{post.status}}</span><time>{{post.updatedAt}}</time></RouterLink></div></section></template>
      <template v-else-if="section==='posts'"><header class="admin-page-header"><div><span>CONTENT / POSTS</span><h1>文章</h1><p>{{adminPosts.length}} 篇内容，按状态和更新时间管理。</p></div><RouterLink class="button button-primary" to="/admin/posts/new"><Plus :size="17" />新建文章</RouterLink></header><div v-if="saved" class="admin-success">{{saved}}</div><div class="admin-toolbar"><div class="admin-search"><Search :size="16" /><input v-model="query" placeholder="搜索标题" /></div><div class="segmented"><button v-for="item in ['ALL','PUBLISHED','DRAFT','PENDING','SCHEDULED','OFFLINE','TRASHED']" :key="item" :class="{active:filter===item}" @click="filter=item">{{item}}</button></div></div><div v-if="selectedPosts.length" class="bulk-bar"><strong>已选择 {{selectedPosts.length}} 篇</strong><button @click="bulkStatus('PUBLISHED')">发布</button><button @click="bulkStatus('OFFLINE')">下线</button><button @click="bulkStatus('TRASHED')">移入回收站</button><button @click="bulkStatus('DRAFT')">恢复为草稿</button></div><section class="admin-panel"><div class="admin-table post-admin-table"><div class="table-head"><span>选择</span><span>文章</span><span>分类</span><span>状态</span><span>更新时间</span><span>操作</span></div><div v-for="post in filteredPosts" :key="post.id" class="table-row"><input v-model="selectedPosts" type="checkbox" :value="String(post.id)" :aria-label="`选择 ${post.title}`" /><RouterLink :to="`/admin/posts/${post.id}/edit`"><strong>{{post.title}}</strong><small>{{post.excerpt}}</small></RouterLink><span>{{post.category}}</span><span class="status">{{post.status}}</span><time>{{post.updatedAt}}</time><RouterLink :to="`/admin/posts/${post.id}/edit`"><FileText :size="15" /></RouterLink></div></div></section></template>
      <template v-else-if="section==='taxonomy'"><header class="admin-page-header"><div><span>CONTENT / TAXONOMY</span><h1>分类与标签</h1><p>删除前检查引用，名称和 slug 保持唯一。</p></div></header><div v-if="saved" class="admin-success">{{saved}}</div><div class="taxonomy-layout"><section class="admin-panel taxonomy-panel"><div class="panel-heading"><div><span>CATEGORIES</span><h2>分类</h2></div></div><form class="taxonomy-form" @submit.prevent="createCategory"><input v-model="taxonomyDraft.name" placeholder="分类名称" /><input v-model="taxonomyDraft.slug" placeholder="unique-slug" /><input v-model="taxonomyDraft.description" placeholder="分类说明" /><button class="button button-primary"><Plus :size="15" />新增分类</button></form><div class="taxonomy-list"><div v-for="item in (categoriesAdmin.length?categoriesAdmin:categories)" :key="item.id||item.name"><FolderTree :size="16" /><div><strong>{{item.name}}</strong><small>/{{item.slug||'category'}} · {{item.description}}</small></div></div></div></section><section class="admin-panel taxonomy-panel"><div class="panel-heading"><div><span>TAGS</span><h2>标签</h2></div></div><form class="taxonomy-form tag-create" @submit.prevent="createTag"><input v-model="tagDraft" placeholder="新标签名称" /><button class="button button-primary"><Plus :size="15" />新增标签</button></form><div class="taxonomy-list tag-list"><div v-for="item in tagsAdmin" :key="item.id"><Hash :size="15" /><div><strong>{{item.name}}</strong><small>/{{item.slug}}</small></div></div><p v-if="!tagsAdmin.length" class="admin-empty">保存文章时会同步标签；也可以在这里预先创建。</p></div></section></div></template>
      <template v-else-if="section==='media'"><header class="admin-page-header"><div><span>LIBRARY / MEDIA</span><h1>媒体库</h1><p>本地项目图片与上传入口。</p></div><label class="button button-primary"><Upload :size="16" />上传文件<input type="file" hidden multiple accept="image/jpeg,image/png,image/webp" @change="uploadMedia" /></label></header><section class="media-grid"><article v-for="item in (media.length?media:[{id:'hero',filename:'hero-circuit.jpg',url:'/assets/hero-circuit.jpg',mimeType:'image/jpeg'},{id:'work',filename:'workstation.jpg',url:'/assets/workstation.jpg',mimeType:'image/jpeg'}])" :key="item.id"><div class="media-thumb"><img :src="item.url" :alt="item.altText||item.filename" /></div><div><strong>{{item.filename}}</strong><span>{{item.mimeType}}</span></div></article></section></template>
      <template v-else-if="section==='comments'"><header class="admin-page-header"><div><span>COMMUNITY / MODERATION</span><h1>评论审核</h1><p>{{comments.filter(c=>c.status==='PENDING').length}} 条评论等待处理。</p></div></header><section class="admin-panel moderation-list"><article v-for="item in comments" :key="item.id"><div class="moderation-meta"><strong>{{item.authorName}}</strong><span class="risk-tag">{{item.status}}</span></div><p>{{item.content}}</p><small>文章：{{item.postSlug}}</small><div class="moderation-actions"><button class="button button-primary" @click="moderate(item,'APPROVED')"><Check :size="15" />通过</button><button class="button" @click="deleteComment(item)"><Trash2 :size="15" />拒绝</button></div></article></section></template>
      <template v-else-if="section==='users'"><header class="admin-page-header"><div><span>ACCESS / USERS</span><h1>用户与角色</h1><p>最小权限原则，关键变更写入操作日志。</p></div><button class="button button-primary"><Plus :size="16" />邀请用户</button></header><div v-if="saved" class="admin-success">{{saved}}</div><section class="admin-panel"><div class="admin-table user-table"><div class="table-head"><span>用户</span><span>角色</span><span>状态</span><span>最近登录</span><span>操作</span></div><div v-for="user in users" :key="user.id" class="table-row"><div><strong>{{user.name}}</strong><small>{{user.email}}</small></div><span>{{user.role}}</span><span>{{user.status}}</span><time>今天</time><button class="row-text-button" @click="toggleUser(user)">{{user.status==='ACTIVE'||user.status==='正常'?'禁用':'启用'}}</button></div></div></section></template>
      <template v-else-if="section==='settings'"><header class="admin-page-header"><div><span>SYSTEM / SETTINGS</span><h1>站点设置</h1><p>基础信息、分享模板和互动功能。</p></div><button class="button button-primary" @click="saveSettings"><Save :size="15" />保存设置</button></header><div v-if="saved" class="admin-success"><Check :size="15" />{{saved}}</div><div class="settings-grid"><section class="admin-panel settings-panel"><div class="panel-heading"><div><span>GENERAL</span><h2>基础信息</h2></div></div><label>站点名称<input v-model="settings.siteName" /></label><label>站点定位语<textarea v-model="settings.tagline" /></label></section><section class="admin-panel settings-panel"><div class="panel-heading"><div><span>SHARE / POSTER</span><h2>分享海报</h2></div></div><label>默认模板<select v-model="settings.shareTemplate"><option>横版卡片</option><option>竖版海报</option></select></label><div class="share-setting-preview"><span>SIGNAL NOTES</span><strong>{{settings.siteName}}</strong><small>{{settings.tagline}}</small><i>QR</i></div></section></div></template>
      <template v-else><header class="admin-page-header"><div><span>SYSTEM / AUDIT</span><h1>日志与备份</h1><p>每次重要变更都有记录，备份可验证且可以恢复。</p></div><button class="button button-primary" @click="backup='刚刚 · 校验通过'"><Archive :size="15" />立即备份</button></header><div class="log-status-grid"><div><ShieldCheck :size="20" /><span>安全检查</span><strong>全部通过</strong><small>最近检查：刚刚</small></div><div><Archive :size="20" /><span>最近备份</span><strong>{{backup}}</strong><small>数据库 + 媒体文件</small></div><div><Activity :size="20" /><span>异步任务</span><strong>0 失败</strong><small>最近 24 小时</small></div></div></template>
    </main>
  </div></div>
</template>
